{% set earnings = doc.earnings | selectattr("statistical_component", "equalto", 0) | selectattr("do_not_include_in_total", "equalto", 0) | list %}
{% set deductions = doc.deductions | selectattr("statistical_component", "equalto", 0) | selectattr("do_not_include_in_total", "equalto", 0) | list %}

{% set inf_earnings = [] %}
{% set inf_deductions = [] %}
{% for row in doc.earnings %}
  {% if row.statistical_component or row.do_not_include_in_total %}
    {% set _ = inf_earnings.append(row) %}
  {% endif %}
{% endfor %}
{% for row in doc.deductions %}
  {% if row.statistical_component or row.do_not_include_in_total %}
    {% set _ = inf_deductions.append(row) %}
  {% endif %}
{% endfor %}
{% set informationals = inf_earnings + inf_deductions %}

{% set ns = namespace(advance_amount = doc.total_loan_repayment or 0) %}
{% if ns.advance_amount == 0 %}
  {% for row in doc.deductions %}
    {% set name_lower = row.salary_component | lower %}
    {% if ns.advance_amount == 0 and ('salary advance' in name_lower or 'advance' in name_lower or 'loan' in name_lower) %}
      {% set ns.advance_amount = row.amount %}
    {% endif %}
  {% endfor %}
{% endif %}

<style>
