    font-size: 9px;
    color: #f0d9a8;
    margin-right: 8px;
    white-space: nowrap;
  }
  .meta-badge b {
    color: #ffffff;
    font-weight: 600;
    margin-left: 4px;
  }

  .accent-bar {
    height: 4px;
    background: #c8973a;
  }

