    background: #f5f7fa;
    padding: 16px 28px;
    border-bottom: 1px solid #dde3ec;
  }
  .section-label {
    font-size: 9px;
    font-weight: bold;
    letter-spacing: 2px;
    text-transform: uppercase;
    color: #c8973a;
    margin-bottom: 10px;
  }
  .personal-table {
    width: 100%;
    border-collapse: collapse;
  }
  .personal-table td {
    width: 33.33%;
    vertical-align: top;
    padding: 0 10px 8px 0;
  }
  .info-label {
    font-size: 8px;
    font-weight: bold;
    text-transform: uppercase;
    letter-spacing: 0.8px;
    color: #6b7a99;
    display: block;
    margin-bottom: 2px;
  }
