    font-size: 11px;
    font-weight: 600;
    color: #1a2744;
    border-bottom: 1px solid #dde3ec;
    padding-bottom: 3px;
    display: block;
  }
  .info-value.highlight {
    font-weight: bold;
  }

  .salary-section {
    padding: 5px 0;
  }

  .two-col-table {
    width: 100%;
    border-collapse: collapse;
    margin-bottom: 5px;
  }
  .two-col-table > tbody > tr > td:first-child { padding-right: 6px; }
  .two-col-table > tbody > tr > td:last-child { padding-left: 6px; }
  .two-col-table > tbody > tr > td {
    width: 50%;
    vertical-align: top;
    padding: 0;
  }

  .table-card {
    border: 1px solid #dde3ec;
    border-radius: 10px;
    overflow: hidden;
    width: 100%;
  }

  .table-hdr {
    padding: 7px 10px;
    font-size: 10px;
    font-weight: bold;
    letter-spacing: 1.5px;
    text-transform: uppercase;
    color: #ffffff;
  }
  .table-hdr.earnings-hdr  { background: #1a2744; }
  .table-hdr.deductions-hdr { background: #7a1a1a; }
  .table-hdr.info-hdr       { background: #1a4a3a; }

  .salary-table {
    width: 100%;
    border-collapse: collapse;
  }
  .salary-table th {
    padding: 5px 10px;
    font-size: 8px;
    font-weight: bold;
    text-transform: uppercase;
    letter-spacing: 0.8px;
    color: #6b7a99;
    background: #f5f7fa;
    border-bottom: 1px solid #dde3ec;
    text-align: left;
  }
  .salary-table th.right { text-align: right; }
  .salary-table td {
    padding: 6px 10px;
    font-size: 10px;
    color: #1a2744;
    border-bottom: 1px solid #dde3ec;
    vertical-align: middle;
