  .salary-table td.right {
    text-align: right;
    font-weight: 600;
  }
  .salary-table tr.alt td { background: #f9fafc; }
  .salary-table tr.total-row td {
    font-weight: bold;
    font-size: 10.5px;
    background: #1a2744;
    color: #ffffff;
    padding: 7px 10px;
    border-top: 2px solid #c8973a;
    border-bottom: none;
