  .salary-table tr.total-row td.right { color: #f0d9a8; }
  .salary-table tr.deduct-total td { background: #7a1a1a; }
  .salary-table tr.info-total td   { background: #1a4a3a; }
  .salary-table tr.empty-row td {
    color: #6b7a99;
    font-style: italic;
    font-size: 9px;
    text-align: center;
  }

  .salary-inner {
    padding: 0 28px;
  }

  .full-width-card {
    width: 100%;
    margin-bottom: 16px;
  }
  .badge-earning {
    color: #1e7e5e;
    font-weight: bold;
    font-size: 8px;
    text-transform: uppercase;
    letter-spacing: 0.5px;
  }
  .badge-deduction {
    color: #b83232;
    font-weight: bold;
    font-size: 8px;
    text-transform: uppercase;
    letter-spacing: 0.5px;
