<div class="slip-wrapper">

  <!-- HEADER -->
  <div class="slip-header">
    <table style="width:100%; border-collapse:collapse;"><tbody><tr>
      <td style="vertical-align:middle; padding:0;">
        <div class="company-name">{{ doc.company }}</div>
        <div class="doc-title">Employee Pay Slip</div>
      </td>
      <td style="vertical-align:middle; text-align:right; width:200px; padding:0 0 0 12px;">
        {% set _logo = frappe.db.get_single_value('Website Settings', 'app_logo') %}
        {% if _logo %}
          <img src="{{ _logo }}"
            style="height:40px; width:200px; object-fit:contain; display:block; margin-left:auto; border-radius:4px; background:#ffffff; ">
        {% endif %}
      </td>
    </tr></tbody></table>
    <table class="header-meta-table"><tbody><tr><td>
      <span class="meta-badge">Period <b>{{ frappe.format_date(doc.start_date, "MMM y") if doc.start_date else doc.month ~ " " ~ doc.fiscal_year }}</b></span>
      <span class="meta-badge">Staff ID <b>{{ doc.employee }}</b></span>
      <span class="meta-badge">Pay Date <b>{{ frappe.format_date(doc.posting_date, "d MMM y") if doc.posting_date else "-" }}</b></span>
      {% if doc.payroll_frequency %}<span class="meta-badge">Frequency <b>{{ doc.payroll_frequency }}</b></span>{% endif %}
    </td></tr></tbody>
    </table>
  </div>
  <div class="accent-bar"></div>

  <!-- PERSONAL DETAILS -->
  <div class="personal-section">
    <div class="section-label">Personal Details</div>
    <table class="personal-table"><tbody>
      <tr>
        <td>
          <span class="info-label">Full Name</span>
          <span class="info-value highlight">{{ doc.employee_name }}</span>
        </td>
        <td>
          <span class="info-label">Job Position / Designation</span>
          <span class="info-value">{{ doc.designation or "-" }}</span>
        </td>
        <td>
          <span class="info-label">Department</span>
          <span class="info-value">{{ doc.department or "-" }}</span>
        </td>
      </tr>
      <tr>
        <td>
          <span class="info-label">Branch</span>
          <span class="info-value">{{ doc.branch or "-" }}</span>
        </td>
        <td>
          <span class="info-label">Bank</span>
          <span class="info-value">{{ doc.bank_name or "-" }}</span>
        </td>
        <td>
          <span class="info-label">Bank Account #</span>
          <span class="info-value">{{ doc.bank_account_no or "-" }}</span>
        </td>
      </tr>
    </tbody></table>
  </div>

  <!-- SALARY TABLES -->
  <div class="salary-section">

    <div style="padding: 0 17px;">
    <table class="two-col-table"><tbody><tr>

      <!-- EARNINGS -->
      <td>
        <div class="table-card">
          <div class="table-hdr earnings-hdr">&#x25B2; Earnings</div>
          <table class="salary-table">
            <thead><tr>
              <th>Component</th>
              <th class="right">Amount (GHS)</th>
            </tr></thead>
            <tbody>
              {% if earnings %}
                {% for row in earnings %}
                <tr{% if loop.index is even %} class="alt"{% endif %}>
                  <td>{{ row.salary_component }}</td>
                  <td class="right">{{ "{:,.2f}".format(row.amount) }}</td>
                </tr>
                {% endfor %}
              {% else %}
                <tr class="empty-row"><td colspan="2">No earnings recorded</td></tr>
              {% endif %}


              <tr class="total-row">
              <td>Total Earnings</td>
              <td class="right">
                {{
                  "{:,.2f}".format(
                    earnings | map(attribute='amount') | map('float') | sum
                    if earnings else 0
                  )
                }}
              </td>
            </tr>
            </tbody>
          </table>
        </div>
      </td>

      <!-- DEDUCTIONS -->
      <td>
        <div class="table-card">
          <div class="table-hdr deductions-hdr">&#x25BC; Deductions</div>
          <table class="salary-table">
            <thead><tr>
              <th>Component</th>
              <th class="right">Amount (GHS)</th>
            </tr></thead>
            <tbody>
              {% if deductions %}
                {% for row in deductions %}
                <tr{% if loop.index is even %} class="alt"{% endif %}>
                  <td>{{ row.salary_component }}</td>
                  <td class="right">{{ "{:,.2f}".format(row.amount) }}</td>
                </tr>
                {% endfor %}
              {% else %}
                <tr class="empty-row"><td colspan="2">No deductions recorded</td></tr>
              {% endif %}
              <tr class="total-row deduct-total">
                <td>Total Deductions</td>
                <td class="right">{{ "{:,.2f}".format(doc.total_deduction or 0) }}</td>
              </tr>
            </tbody>
          </table>
        </div>
      </td>

    </tr></tbody></table>
    </div><!-- /two-col-wrapper -->

    <div class="salary-inner">
    <!-- INFORMATIONALS -->
    {% if informationals %}
    <div class="full-width-card table-card" style="margin-bottom:16px;">
      <div class="table-hdr info-hdr"><i>&#x2139;</i> Informational Salary Components &mdash; (Unclaimable)</div>
      <table class="salary-table">
        <thead><tr>
          <th>Component</th>
          <th>Type</th>
          <th class="right">Amount (GHS)</th>
        </tr></thead>
        <tbody>
          {% for row in inf_earnings %}
          <tr{% if loop.index is even %} class="alt"{% endif %}>
            <td>{{ row.salary_component }}</td>
            <td><span class="badge-earning">Other Benefits</span></td>
            <td class="right amt-green">{{ "{:,.2f}".format(row.amount) }}</td>
          </tr>
          {% endfor %}
          {% for row in inf_deductions %}
          <tr{% if (loop.index + inf_earnings|length) is even %} class="alt"{% endif %}>
            <td>{{ row.salary_component }}</td>
            <td><span class="badge-deduction">Deduction</span></td>
            <td class="right amt-red">{{ "{:,.2f}".format(row.amount) }}</td>
          </tr>
          {% endfor %}
        </tbody>
      </table>
    </div>
    {% endif %}

    <!-- NET PAY BANNER -->
    <div class="net-pay-banner">
      <table class="net-pay-inner"><tbody><tr>
        <td>
          <span class="net-pay-label">Net Pay Check</span>
          <span class="net-pay-sublabel">Amount payable for {{ frappe.format_date(doc.start_date, "MMMM y") if doc.start_date else doc.month ~ " " ~ doc.fiscal_year }}</span>
        </td>
        <td>
          <div class="net-pay-amount">
            <span class="net-pay-currency">GHS</span>
            {{ "{:,.2f}".format(
              (earnings | map(attribute='amount') | map('float') | sum if earnings else 0.0) -
              (deductions | map(attribute='amount') | map('float') | sum if deductions else 0.0)
            ) }}
          </div>
        </td>
      </tr></tbody></table>
    </div>

    </div><!-- /salary-inner -->
  </div><!-- /salary-section -->

  <!-- FOOTER -->
  <div class="slip-footer">
    <table class="footer-inner"><tbody><tr>
      <td>
        <div class="footer-note">
          This is a computer-generated payslip and does not require a physical signature.<br>
          For queries, contact the HR &amp; Payroll department.<br>
          Confidential &mdash; For the named employee only.
        </div>
      </td>
      <td class="sig-td">
        <div class="sig-line"></div>
        <div class="sig-label">Authorised Signatory</div>
      </td>
    </tr></tbody></table>
  </div>

</div>

